 'engine',current_setting('server_version_num'),
 'helpers',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'identity',pg_get_function_identity_arguments(p.oid),'owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text,'md5',md5(pg_get_functiondef(p.oid))) ORDER BY n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE (n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) IN (('auth','jwt',''),('auth','role',''),('auth','uid',''),('private','has_platform_role','_user_id uuid, _role platform_role'),('private','has_tenant_role','_user_id uuid, _tenant_id uuid, _role tenant_role'),('private','is_platform_admin','_user_id uuid'),('private','is_tenant_member','_user_id uuid, _tenant_id uuid'),('private','recon_authoritative_access_decision','_recon uuid, _action text'),('private','recon_authoritative_access_decision_as','_actor uuid, _recon uuid, _action text'),('private','recon_platform_support_grant_active','_actor uuid, _tenant_id uuid, _capability text'),('private','recon_result_missing_sides','_payload jsonb'),('private','user_can_access_recon','_user uuid, _recon uuid, _perm text'),('public','audit_log_block_mutation',''),('public','audit_log_chain',''),('public','get_recon_run_result_page','_tenant_id uuid, _run_id uuid, _page integer, _status text'),('public','get_recon_run_result_status_counts','_tenant_id uuid, _run_id uuid'),('public','guard_api_token_principal_metadata',''),('public','has_platform_role','_user_id uuid, _role platform_role'),('public','has_tenant_role','_user_id uuid, _tenant_id uuid, _role tenant_role'),('public','is_platform_admin','_user_id uuid'),('public','is_tenant_member','_user_id uuid, _tenant_id uuid'),('public','recon_authoritative_access_decision','_recon uuid, _action text'),('public','recon_authoritative_access_decision_as','_actor uuid, _recon uuid, _action text'),('public','user_can_access_recon','_user uuid, _recon uuid, _perm text'))),
 'relations',(SELECT jsonb_agg(jsonb_build_object('relname',c.relname,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text,'relrowsecurity',c.relrowsecurity,'relforcerowsecurity',c.relforcerowsecurity) ORDER BY c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('api_service_principals','api_tokens','audit_chain_head','audit_log','bu_group_assignments','bu_user_assignments','business_units','platform_roles','platform_support_grants','recon_definition_bu_grants','recon_definition_business_units','recon_definitions','recon_exceptions','recon_matches','recon_permissions','recon_runs','tenant_group_members','tenant_groups','tenant_members','tenants')),
 'types',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'position',a.attnum) ORDER BY c.relname,a.attnum) FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('api_service_principals','api_tokens','audit_chain_head','audit_log','bu_group_assignments','bu_user_assignments','business_units','platform_roles','platform_support_grants','recon_definition_bu_grants','recon_definition_business_units','recon_definitions','recon_exceptions','recon_matches','recon_permissions','recon_runs','tenant_group_members','tenant_groups','tenant_members','tenants') AND a.attnum>0 AND NOT a.attisdropped),
 'core_columns',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'position',a.attnum,'acl',a.attacl::text,'identity',a.attidentity,'generated',a.attgenerated,'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid)) ORDER BY c.relname,a.attnum) FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE n.nspname='public' AND c.relname IN ('api_tokens','audit_log','audit_chain_head') AND a.attnum>0 AND NOT a.attisdropped),
 'constraints',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',k.conname,'type',k.contype,'validated',k.convalidated,'definition',pg_get_constraintdef(k.oid)) ORDER BY c.relname,k.conname) FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('api_tokens','audit_log','audit_chain_head')),
 'indexes',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'definition',pg_get_indexdef(i.indexrelid)) ORDER BY c.relname,pg_get_indexdef(i.indexrelid)) FROM pg_index i JOIN pg_class c ON c.oid=i.indrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname='api_tokens'),
 'policies',(SELECT jsonb_agg(to_jsonb(p) ORDER BY p.tablename,p.policyname) FROM pg_policies p WHERE p.schemaname='public' AND p.tablename='api_tokens'),
 'triggers',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid),'md5',md5(pg_get_functiondef(t.tgfoid))) ORDER BY c.relname,t.tgname) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('api_tokens','audit_log') AND NOT t.tgisinternal)
) AS actual) captured;
