-- Additional immutable guard; existing classification/issuer alias are reused.
-- Applies no UPDATE/backfill to existing rows and denies reclassification even by service.
CREATE FUNCTION private.guard_qualified_api_token_identity() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public,auth AS $guard$
BEGIN
 IF TG_OP='UPDATE' AND (NEW.id IS DISTINCT FROM OLD.id
   OR NEW.created_at IS DISTINCT FROM OLD.created_at
   OR NEW.principal_kind IS DISTINCT FROM OLD.principal_kind
   OR NEW.subject_user_id IS DISTINCT FROM OLD.subject_user_id
   OR NEW.service_principal_id IS DISTINCT FROM OLD.service_principal_id
   OR NEW.scopes IS DISTINCT FROM OLD.scopes OR NEW.expires_at IS DISTINCT FROM OLD.expires_at
   OR (OLD.revoked_at IS NOT NULL AND NEW.revoked_at IS DISTINCT FROM OLD.revoked_at)) THEN
   RAISE EXCEPTION 'immutable_api_token_binding' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $guard$;
REVOKE ALL ON FUNCTION private.guard_qualified_api_token_identity() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER guard_qualified_api_token_identity_before_update BEFORE UPDATE ON public.api_tokens
FOR EACH ROW EXECUTE FUNCTION private.guard_qualified_api_token_identity();

-- Shared with Heisenberg through parent. Only trusted, named service RPCs can
-- invoke this private helper; it returns principal metadata, never business data.
CREATE FUNCTION private.qualified_user_delegated_api_token(
 _token_id uuid,_tenant_id uuid,_required_scope text
) RETURNS TABLE(token_id uuid,tenant_id uuid,actor_user_id uuid,principal_kind text,expires_at timestamptz,scopes text[])
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,auth SET row_security=on AS $principal$
DECLARE token_row public.api_tokens%ROWTYPE;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' OR current_setting('role',true) IS DISTINCT FROM 'service_role'
   OR _required_scope IS NULL OR _required_scope NOT IN ('recons.read','ai.inference') THEN
   RAISE EXCEPTION 'not permitted' USING ERRCODE='42501';
 END IF;
 SELECT t.* INTO token_row FROM public.api_tokens t WHERE t.id=_token_id AND t.tenant_id=_tenant_id
   AND t.principal_kind='user_delegated' AND t.subject_user_id=t.created_by AND t.issuer_user_id=t.created_by
   AND t.service_principal_id IS NULL AND t.revoked_at IS NULL AND t.created_by IS NOT NULL
   AND (t.expires_at IS NULL OR t.expires_at>clock_timestamp()) AND _required_scope=ANY(t.scopes) FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'not permitted' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.tenant_members m WHERE m.tenant_id=_tenant_id AND m.user_id=token_row.subject_user_id AND m.active=true FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'not permitted' USING ERRCODE='42501'; END IF;
 RETURN QUERY SELECT token_row.id,token_row.tenant_id,token_row.subject_user_id,token_row.principal_kind,token_row.expires_at,token_row.scopes;
END $principal$;
REVOKE ALL ON FUNCTION private.qualified_user_delegated_api_token(uuid,uuid,text) FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION public.issue_user_delegated_api_token(
 _tenant_id uuid,_name text,_prefix text,_token_hash text,_scopes text[],_expires_at timestamptz
) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path=pg_catalog,public,auth SET row_security=on AS $issue$
DECLARE actor uuid := auth.uid(); token_id uuid; audit_id bigint; slug text;
BEGIN
 IF auth.role() IS DISTINCT FROM 'authenticated' OR current_setting('role',true) IS DISTINCT FROM 'authenticated'
   OR actor IS NULL THEN RAISE EXCEPTION 'not permitted' USING ERRCODE='42501'; END IF;
 IF _tenant_id IS NULL OR _name IS NULL OR length(btrim(_name)) NOT BETWEEN 1 AND 120
   OR _prefix IS NULL OR _prefix !~ '^fvi_[0-9a-f]{8}$'
   OR _token_hash IS NULL OR _token_hash !~ '^[0-9a-f]{64}$'
   OR _scopes IS NULL OR cardinality(_scopes) NOT BETWEEN 1 AND 22
   OR array_position(_scopes,NULL) IS NOT NULL OR NOT (_scopes <@ ARRAY['recons.read','recons.run','breaks.write','connectors.read','connectors.run','connectors.agent','watchers.read','watchers.write','data-prep.read','data-prep.write','data-prep.run','data-prep.approve','data-prep.promote','reference-data.read','reference-data.write','reference-data.approve','reports.read','environment-changes.read','environment-changes.write','environment-changes.approve','ai.inference','aidp:extract']::text[])
   OR cardinality(_scopes)<>(SELECT count(DISTINCT s) FROM unnest(_scopes) s)
   OR (_expires_at IS NOT NULL AND (_expires_at<=clock_timestamp() OR _expires_at>clock_timestamp()+interval '730 days')) THEN
   RAISE EXCEPTION 'invalid token issuance input' USING ERRCODE='22023';
 END IF;
 PERFORM 1 FROM public.tenant_members WHERE tenant_id=_tenant_id AND user_id=actor AND active=true AND role='tenant_admin' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'not permitted' USING ERRCODE='42501'; END IF;
 SELECT t.slug INTO slug FROM public.tenants t WHERE t.id=_tenant_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'not permitted' USING ERRCODE='42501'; END IF;
 -- Reject hash reuse without printing any token/hash. Existing hash index is nonunique.
 PERFORM pg_advisory_xact_lock(hashtextextended(_token_hash,743301));
 IF EXISTS(SELECT 1 FROM public.api_tokens WHERE token_hash=_token_hash) THEN
   RAISE EXCEPTION 'token collision' USING ERRCODE='23505';
 END IF;
 INSERT INTO public.api_tokens(tenant_id,name,prefix,token_hash,scopes,expires_at,created_by,principal_kind,subject_user_id)
 VALUES(_tenant_id,btrim(_name),_prefix,_token_hash,_scopes,_expires_at,actor,'user_delegated',actor) RETURNING id INTO token_id;
 INSERT INTO public.audit_log(tenant_id,tenant_slug,actor_user_id,scope,action,resource_type,resource_id,context)
 VALUES(_tenant_id,slug,actor,'tenant','api.token.create','api_tokens',token_id::text,
   jsonb_build_object('name',btrim(_name),'scopes',_scopes,'principal_kind','user_delegated','subject_user_id',actor)) RETURNING id INTO audit_id;
 IF NOT EXISTS(SELECT 1 FROM public.audit_log a JOIN public.audit_chain_head h ON h.singleton=true
   AND h.last_audit_id=a.id AND h.last_hash=a.row_hash WHERE a.id=audit_id
   AND a.actor_user_id=actor AND a.tenant_id=_tenant_id AND a.resource_id=token_id::text AND octet_length(a.row_hash)=32) THEN
   RAISE EXCEPTION 'token issuance audit receipt absent';
 END IF;
 RETURN jsonb_build_object('id',token_id,'audit_id',audit_id::text);
END $issue$;
REVOKE ALL ON FUNCTION public.issue_user_delegated_api_token(uuid,text,text,text,text[],timestamptz) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.issue_user_delegated_api_token(uuid,text,text,text,text[],timestamptz) TO authenticated;

CREATE FUNCTION public.revoke_user_delegated_api_token(_tenant_id uuid,_token_id uuid)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path=pg_catalog,public,auth SET row_security=on AS $revoke$
DECLARE actor uuid := auth.uid(); audit_id bigint; slug text;
BEGIN
 IF auth.role() IS DISTINCT FROM 'authenticated' OR current_setting('role',true) IS DISTINCT FROM 'authenticated'
   OR actor IS NULL THEN RAISE EXCEPTION 'not permitted' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.tenant_members WHERE tenant_id=_tenant_id AND user_id=actor AND active=true AND role='tenant_admin' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'not permitted' USING ERRCODE='42501'; END IF;
 SELECT t.slug INTO slug FROM public.tenants t WHERE t.id=_tenant_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'not permitted' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.api_tokens WHERE id=_token_id AND tenant_id=_tenant_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'not permitted' USING ERRCODE='42501'; END IF;
 -- Idempotent repeat keeps the existing timestamp and creates an attributed receipt.
 UPDATE public.api_tokens SET revoked_at=coalesce(revoked_at,clock_timestamp()) WHERE id=_token_id AND tenant_id=_tenant_id;
 INSERT INTO public.audit_log(tenant_id,tenant_slug,actor_user_id,scope,action,resource_type,resource_id,context)
 VALUES(_tenant_id,slug,actor,'tenant','api.token.revoke','api_tokens',_token_id::text,'{}') RETURNING id INTO audit_id;
 IF NOT EXISTS(SELECT 1 FROM public.audit_log a JOIN public.audit_chain_head h ON h.singleton=true
   AND h.last_audit_id=a.id AND h.last_hash=a.row_hash WHERE a.id=audit_id
   AND a.actor_user_id=actor AND a.tenant_id=_tenant_id AND a.resource_id=_token_id::text AND octet_length(a.row_hash)=32) THEN
   RAISE EXCEPTION 'token revocation audit receipt absent';
 END IF;
 RETURN jsonb_build_object('id',_token_id,'audit_id',audit_id::text);
END $revoke$;
REVOKE ALL ON FUNCTION public.revoke_user_delegated_api_token(uuid,uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.revoke_user_delegated_api_token(uuid,uuid) TO authenticated;

CREATE FUNCTION private.recon_api_persisted_result_page(_tenant_id uuid, _run_id uuid, _page integer DEFAULT 0, _status text DEFAULT 'all'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'private'
 SET row_security TO 'on'
AS $function$
DECLARE
  definition_id uuid;
  result jsonb;
BEGIN
  IF _tenant_id IS NULL OR _run_id IS NULL OR _page IS NULL OR _page < 0 THEN
    RAISE EXCEPTION 'tenant, run and non-negative page are required' USING ERRCODE = '22023';
  END IF;
  IF _status IS NULL OR _status NOT IN ('all','match','partial','missing','duplicate','invalid_key','other','unavailable') THEN
    RAISE EXCEPTION 'unsupported run result status' USING ERRCODE = '22023';
  END IF;

  WITH exception_base AS (
    SELECT e.*,
      CASE WHEN e.payload->>'disposition' = 'keyless_input' THEN 'invalid_key'
        WHEN CASE WHEN jsonb_typeof(private.recon_result_missing_sides(e.payload)) = 'array' THEN jsonb_array_length(private.recon_result_missing_sides(e.payload)) > 0 ELSE false END THEN 'missing'
        WHEN e.payload->>'rule_kind' = 'unique' THEN 'duplicate'
        WHEN jsonb_typeof(e.payload->'key') = 'string' AND jsonb_typeof(e.payload->'sides') = 'object' THEN 'partial'
        WHEN e.payload IS NULL OR e.payload = '{}'::jsonb THEN 'unavailable' ELSE 'other' END AS status_bucket,
      CASE WHEN CASE WHEN jsonb_typeof(private.recon_result_missing_sides(e.payload)) = 'array' THEN jsonb_array_length(private.recon_result_missing_sides(e.payload)) > 0 ELSE false END
          AND jsonb_typeof(e.payload->'key') = 'string'
        THEN 'missing:' || jsonb_build_array(e.payload->'key', private.recon_result_missing_sides(e.payload))::text
        ELSE 'exception:' || e.id::text END AS parent_key
    FROM public.recon_exceptions e WHERE e.tenant_id = _tenant_id AND e.run_id = _run_id
  ), exception_items AS (
    SELECT parent_key, status_bucket, min(created_at) AS created_at,
      jsonb_agg(jsonb_build_object('id',id,'public_case_id',public_case_id,'side',side,'reason',reason,'status',status,
        'payload',payload,'created_at',created_at) ORDER BY created_at,id) AS items
    FROM exception_base GROUP BY parent_key,status_bucket
  ), source_rows AS (
    SELECT parent_key, side, jsonb_agg(source_row ORDER BY created_at,id,member_order) AS rows
    FROM (
      SELECT parent_key,side,payload->'row' AS source_row,created_at,id,1 AS member_order
      FROM exception_base WHERE jsonb_typeof(payload->'row') = 'object'
      UNION ALL
      SELECT e.parent_key,side_entry.key,member_rows.row_data,e.created_at,e.id,member_rows.ordinality::integer
      FROM exception_base e
      CROSS JOIN LATERAL jsonb_each(CASE WHEN jsonb_typeof(e.payload->'members')='object' THEN e.payload->'members' WHEN jsonb_typeof(e.payload->'sides')='object' THEN e.payload->'sides' ELSE '{}'::jsonb END) side_entry
      CROSS JOIN LATERAL jsonb_array_elements(
        CASE WHEN jsonb_typeof(side_entry.value)='array' THEN side_entry.value ELSE jsonb_build_array(side_entry.value) END
      ) WITH ORDINALITY AS member_rows(row_data,ordinality)
    ) values_by_side
    GROUP BY parent_key,side
  ), source_members AS (
    SELECT parent_key, jsonb_object_agg(side,rows) AS members
    FROM source_rows GROUP BY parent_key
  ), exception_parents AS (
    SELECT i.parent_key,i.status_bucket,i.created_at,i.items,
      COALESCE(s.members,'{}'::jsonb) AS members
    FROM exception_items i LEFT JOIN source_members s USING (parent_key)
  ), result_rows AS (
    SELECT m.created_at,'match:'||m.id::text AS result_id,'match'::text AS status_bucket,
      jsonb_build_object('kind','match','id',m.id,'created_at',m.created_at,'rule_id',m.rule_id,
        'cardinality',m.cardinality,'members',m.members,'exception_items','[]'::jsonb) AS row
    FROM public.recon_matches m WHERE m.tenant_id=_tenant_id AND m.run_id=_run_id
    UNION ALL
    SELECT p.created_at,p.parent_key,p.status_bucket,
      jsonb_build_object('kind','exception','id',p.parent_key,'created_at',p.created_at,
        'status_bucket',p.status_bucket,'members',p.members,'exception_items',p.items) AS row
    FROM exception_parents p
  ), filtered AS (
    SELECT * FROM result_rows WHERE _status='all' OR status_bucket=_status
  ), counts AS (
    SELECT count(*) AS parent_count FROM filtered
  ), page AS (
    SELECT row,created_at,result_id FROM filtered ORDER BY created_at,result_id OFFSET _page*50 LIMIT 50
  ), fields AS (
    SELECT COALESCE(jsonb_agg(field_name ORDER BY field_name),'[]'::jsonb) AS names
    FROM (
      SELECT DISTINCT field_name FROM (
        SELECT field.key AS field_name
        FROM public.recon_matches m
        CROSS JOIN LATERAL jsonb_each(CASE WHEN jsonb_typeof(m.members)='object' THEN m.members ELSE '{}'::jsonb END) side
        CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(side.value)='array' THEN side.value ELSE jsonb_build_array(side.value) END) member
        CROSS JOIN LATERAL jsonb_object_keys(CASE WHEN jsonb_typeof(member.value)='object' THEN member.value ELSE '{}'::jsonb END) field(key)
        WHERE m.tenant_id=_tenant_id AND m.run_id=_run_id
        UNION ALL
        SELECT field.key
        FROM public.recon_exceptions e
        CROSS JOIN LATERAL jsonb_object_keys(CASE WHEN jsonb_typeof(e.payload->'row')='object' THEN e.payload->'row' ELSE '{}'::jsonb END) field(key)
        WHERE e.tenant_id=_tenant_id AND e.run_id=_run_id
        UNION ALL
        SELECT field.key
        FROM public.recon_exceptions e
        CROSS JOIN LATERAL jsonb_each(CASE WHEN jsonb_typeof(e.payload->'members')='object' THEN e.payload->'members' WHEN jsonb_typeof(e.payload->'sides')='object' THEN e.payload->'sides' ELSE '{}'::jsonb END) side
        CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(side.value)='array' THEN side.value ELSE jsonb_build_array(side.value) END) AS member_rows(row_data)
        CROSS JOIN LATERAL jsonb_object_keys(CASE WHEN jsonb_typeof(member_rows.row_data)='object' THEN member_rows.row_data ELSE '{}'::jsonb END) field(key)
        WHERE e.tenant_id=_tenant_id AND e.run_id=_run_id
      ) all_fields
    ) distinct_fields
  )
  SELECT jsonb_build_object('rows',COALESCE((SELECT jsonb_agg(page.row ORDER BY page.created_at,page.result_id) FROM page),'[]'::jsonb),
    'field_names',fields.names,
    'parent_count',counts.parent_count,'page',_page,'page_size',50,
    'has_next',((_page+1)*50 < counts.parent_count)) INTO result FROM counts CROSS JOIN fields;
  RETURN result;
END;
$function$
;

REVOKE ALL ON FUNCTION private.recon_api_persisted_result_page(uuid,uuid,integer,text) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION private.recon_api_persisted_result_counts(_tenant_id uuid, _run_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'private'
 SET row_security TO 'on'
AS $function$
DECLARE
  definition_id uuid;
  match_groups bigint;
  exception_items bigint;
  buckets jsonb;
BEGIN
  IF _tenant_id IS NULL OR _run_id IS NULL THEN
    RAISE EXCEPTION 'tenant and run are required' USING ERRCODE = '22023';
  END IF;
  SELECT count(*) INTO match_groups FROM public.recon_matches m
    WHERE m.tenant_id = _tenant_id AND m.run_id = _run_id;
  WITH categorized AS (
    SELECT CASE
      WHEN e.payload->>'disposition' = 'keyless_input' THEN 'invalid_key'
      WHEN CASE WHEN jsonb_typeof(private.recon_result_missing_sides(e.payload)) = 'array' THEN jsonb_array_length(private.recon_result_missing_sides(e.payload)) > 0 ELSE false END THEN 'missing'
      WHEN e.payload->>'rule_kind' = 'unique' THEN 'duplicate'
      WHEN jsonb_typeof(e.payload->'key') = 'string' AND jsonb_typeof(e.payload->'sides') = 'object' THEN 'partial'
      WHEN e.payload IS NULL OR e.payload = '{}'::jsonb THEN 'unavailable'
      ELSE 'other' END AS status_bucket
    FROM public.recon_exceptions e WHERE e.tenant_id = _tenant_id AND e.run_id = _run_id
  ), totals AS (
    SELECT status_bucket,count(*) AS item_count FROM categorized GROUP BY status_bucket
  )
  SELECT (SELECT count(*) FROM categorized), jsonb_build_object(
    'partial',COALESCE((SELECT item_count FROM totals WHERE status_bucket='partial'),0),
    'missing',COALESCE((SELECT item_count FROM totals WHERE status_bucket='missing'),0),
    'duplicate',COALESCE((SELECT item_count FROM totals WHERE status_bucket='duplicate'),0),
    'invalid_key',COALESCE((SELECT item_count FROM totals WHERE status_bucket='invalid_key'),0),
    'other',COALESCE((SELECT item_count FROM totals WHERE status_bucket='other'),0),
    'unavailable',COALESCE((SELECT item_count FROM totals WHERE status_bucket='unavailable'),0)
  ) INTO exception_items,buckets;
  RETURN jsonb_build_object('run_id', _run_id, 'match_groups', match_groups,
    'exception_items', exception_items, 'exception_buckets', buckets,
    'semantics', jsonb_build_object('match','persisted recon_matches groups',
      'partial','exception items with persisted key and sides, excluding missing, duplicate and keyless markers',
      'missing','exception items with a non-empty persisted missing_sides array',
      'duplicate','exception items with persisted rule_kind unique',
      'invalid_key','exception items with persisted disposition keyless_input',
      'other','non-empty legacy payload not classified by the markers above',
      'unavailable','exception items with no usable payload', 'workflow_status_is_separate',true));
END;
$function$
;

REVOKE ALL ON FUNCTION private.recon_api_persisted_result_counts(uuid,uuid) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.read_reconciliation_runs_for_api(
 _token_id uuid,_tenant_id uuid,_tenant_slug text,_recon_id uuid,
 _mode text,_run_id uuid,_page integer,_days integer,_status text,_request_id uuid
) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path=pg_catalog,public,private,auth SET row_security=on AS $read$
DECLARE actor uuid; token_row public.api_tokens%ROWTYPE; payload jsonb; rows_json jsonb;
 run_json jsonb; page_json jsonb; counts_json jsonb; total bigint; audit_id bigint; since_time timestamptz;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' OR current_setting('role',true) IS DISTINCT FROM 'service_role' THEN
   RAISE EXCEPTION 'not permitted' USING ERRCODE='42501';
 END IF;
 IF _token_id IS NULL OR _tenant_id IS NULL OR _tenant_slug IS NULL OR _recon_id IS NULL
   OR _page IS NULL OR _page NOT BETWEEN 1 AND 10000 OR _mode IS NULL OR _mode NOT IN ('history','results')
   OR _days IS NULL OR _days NOT IN (1,7,14,30,90)
   OR _status IS NULL OR _status NOT IN ('all','match','partial','missing','duplicate','invalid_key','other','unavailable')
   OR (_mode='results' AND _run_id IS NULL) OR (_mode='history' AND (_run_id IS NOT NULL OR _status<>'all')) THEN
   RAISE EXCEPTION 'invalid read input' USING ERRCODE='22023';
 END IF;
 SELECT p.actor_user_id INTO actor FROM private.qualified_user_delegated_api_token(_token_id,_tenant_id,'recons.read') p;
 SELECT t.* INTO token_row FROM public.api_tokens t WHERE t.id=_token_id;
 -- Locks serialize read-before-revoke. Revocation committed first is denied.
 PERFORM 1 FROM public.tenant_members WHERE tenant_id=_tenant_id AND user_id=actor AND active=true FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'not permitted' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.tenants WHERE id=_tenant_id AND slug=_tenant_slug FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'read not found' USING ERRCODE='P0002'; END IF;
 PERFORM 1 FROM public.recon_definitions WHERE id=_recon_id AND tenant_id=_tenant_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'read not found' USING ERRCODE='P0002'; END IF;
 -- Lock current authorization inputs, always by token actor/target. No table lock,
 -- caller-selected actor, JWT override, role switch or general privileged proxy.
 PERFORM 1 FROM public.recon_definition_business_units WHERE recon_id=_recon_id FOR SHARE;
 PERFORM 1 FROM public.recon_definition_bu_grants WHERE recon_id=_recon_id FOR SHARE;
 PERFORM 1 FROM public.recon_permissions WHERE recon_id=_recon_id FOR SHARE;
 PERFORM 1 FROM public.tenant_group_members gm JOIN public.tenant_groups g ON g.id=gm.group_id
   WHERE gm.user_id=actor AND g.tenant_id=_tenant_id FOR SHARE OF gm,g;
 PERFORM 1 FROM public.bu_user_assignments WHERE tenant_id=_tenant_id AND user_id=actor FOR SHARE;
 PERFORM 1 FROM public.bu_group_assignments ga JOIN public.tenant_group_members gm ON gm.group_id=ga.group_id
   WHERE ga.tenant_id=_tenant_id AND gm.user_id=actor FOR SHARE OF ga;
 PERFORM 1 FROM public.business_units WHERE tenant_id=_tenant_id AND id IN (
   SELECT bu_id FROM public.recon_definition_business_units WHERE recon_id=_recon_id
   UNION SELECT bu_id FROM public.bu_user_assignments WHERE tenant_id=_tenant_id AND user_id=actor
   UNION SELECT ga.bu_id FROM public.bu_group_assignments ga JOIN public.tenant_group_members gm ON gm.group_id=ga.group_id
     WHERE ga.tenant_id=_tenant_id AND gm.user_id=actor) FOR SHARE;
 PERFORM 1 FROM public.platform_roles WHERE user_id=actor FOR SHARE;
 PERFORM 1 FROM public.platform_support_grants WHERE actor_id=actor AND tenant_id=_tenant_id FOR SHARE;
 IF public.recon_authoritative_access_decision_as(actor,_recon_id,'view') IS DISTINCT FROM true THEN
   RAISE EXCEPTION 'not permitted' USING ERRCODE='42501';
 END IF;
 IF _mode='history' THEN
   since_time := statement_timestamp()-make_interval(days=>_days);
   -- One statement/snapshot for total AND page so concurrent new runs cannot
   -- disagree with has_next or total. All projections remain tenant/recon scoped.
   WITH scoped AS MATERIALIZED (
     SELECT id,run_uid,definition_id,status,matched_count,exception_count,total_rows,started_at,completed_at,
       CASE WHEN jsonb_typeof(stats->'matched_records')='number' THEN stats->'matched_records' ELSE 'null'::jsonb END AS matched_input_memberships
     FROM public.recon_runs WHERE tenant_id=_tenant_id AND definition_id=_recon_id AND started_at>=since_time
   ), page_rows AS (SELECT * FROM scoped ORDER BY started_at DESC,id ASC OFFSET ((_page-1)*50) LIMIT 50)
   SELECT (SELECT count(*) FROM scoped),coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.started_at DESC,p.id ASC),'[]')
     INTO total,rows_json FROM page_rows p;
   payload := jsonb_build_object('rows',rows_json,'total',total,'page',_page,'page_size',50,'has_next',_page::bigint*50<total);
 ELSE
   PERFORM 1 FROM public.recon_runs WHERE id=_run_id AND tenant_id=_tenant_id AND definition_id=_recon_id FOR SHARE;
   IF NOT FOUND THEN RAISE EXCEPTION 'read not found' USING ERRCODE='P0002'; END IF;
   -- Same statement snapshot for stored run metadata, result parents and counts.
   SELECT to_jsonb(r),private.recon_api_persisted_result_page(_tenant_id,_run_id,_page-1,_status),
     private.recon_api_persisted_result_counts(_tenant_id,_run_id)
   INTO run_json,page_json,counts_json FROM (
     SELECT id,run_uid,definition_id,status,matched_count,exception_count,total_rows,started_at,completed_at,
       CASE WHEN jsonb_typeof(stats->'matched_records')='number' THEN stats->'matched_records' ELSE 'null'::jsonb END AS matched_input_memberships
     FROM public.recon_runs WHERE id=_run_id AND tenant_id=_tenant_id AND definition_id=_recon_id) r;
   IF page_json IS NULL OR (page_json->>'page_size')::integer IS DISTINCT FROM 50 THEN
     RAISE EXCEPTION 'result paging contract drift';
   END IF;
   payload := jsonb_build_object('run',run_json,'results',page_json->'rows','field_names',page_json->'field_names',
     'parent_count',page_json->'parent_count','page',_page,'page_size',50,'has_next',page_json->'has_next','status_counts',counts_json);
 END IF;
 IF (token_row.expires_at IS NOT NULL AND token_row.expires_at<=clock_timestamp())
   OR public.recon_authoritative_access_decision_as(actor,_recon_id,'view') IS DISTINCT FROM true THEN
   RAISE EXCEPTION 'not permitted' USING ERRCODE='42501';
 END IF;
 INSERT INTO public.audit_log(tenant_id,tenant_slug,actor_user_id,scope,action,resource_type,resource_id,context)
 VALUES(_tenant_id,_tenant_slug,actor,'api',
   CASE WHEN _mode='history' THEN 'api.reconciliation.run_history.read' ELSE 'api.reconciliation.run_results.read' END,
   CASE WHEN _mode='history' THEN 'recon_definition' ELSE 'recon_run' END,coalesce(_run_id,_recon_id)::text,
   jsonb_build_object('api_token_id',_token_id,'principal_kind','user_delegated','recon_id',_recon_id,
     'page',_page,'days',_days,'status',_status,'api_request_id',_request_id)) RETURNING id INTO audit_id;
 -- Insert returning includes AFTER-trigger completion. Require positive int8 receipt.
 IF audit_id IS NULL OR audit_id<=0 OR NOT EXISTS(SELECT 1 FROM public.audit_log a
   JOIN public.audit_chain_head h ON h.singleton=true AND h.last_audit_id=a.id AND h.last_hash=a.row_hash
   WHERE a.id=audit_id AND a.actor_user_id=actor AND a.tenant_id=_tenant_id
     AND a.resource_id=coalesce(_run_id,_recon_id)::text AND a.context->>'api_token_id'=_token_id::text
     AND octet_length(a.row_hash)=32)
   OR (token_row.expires_at IS NOT NULL AND token_row.expires_at<=clock_timestamp()) THEN
   RAISE EXCEPTION 'read audit receipt absent';
 END IF;
 RETURN payload||jsonb_build_object('audit_id',audit_id::text);
END $read$;
REVOKE ALL ON FUNCTION public.read_reconciliation_runs_for_api(uuid,uuid,text,uuid,text,uuid,integer,integer,text,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.read_reconciliation_runs_for_api(uuid,uuid,text,uuid,text,uuid,integer,integer,text,uuid) TO service_role;

COMMIT;
